// The branded illustration set:
// - SpecIllustration: isometric scenes for property specs, each hiding the
//   BalkanEstate two-tower mark somewhere small.
// - SoftIcon: soft 3D icons for use inside pages, drawn to sit beside the
//   sidebar pictures.
// - NavPicture: the 3D sidebar pictures themselves (public/images/nav), for
//   other navigation that points at the same places.
// - CategoryPicture: the home page category tiles (public/images/categories).
//
// The SVGs are generated by scripts/illustrations/generate.mjs into
// public/images/illustrations; edit the drawings there, not the files. The
// .webp pictures are hand-made art, added to their folder as they are.

import React, { useState } from 'react';
import type { SOFT_ICONS, SPEC_ILLUSTRATIONS } from './names.generated';

export type SpecIllustrationName = (typeof SPEC_ILLUSTRATIONS)[number];
export type SoftIconName = (typeof SOFT_ICONS)[number];
export type NavPictureName =
  | 'account' | 'agencies' | 'agents' | 'analytics' | 'blog' | 'business' | 'buy'
  | 'explore' | 'home' | 'how-it-works' | 'inbox' | 'language' | 'logout'
  | 'new-listing' | 'rent' | 'saved' | 'saved-searches' | 'subscription'
  | 'tools' | 'villas';
export type CategoryPictureName = 'apartments' | 'houses' | 'villas' | 'land' | 'rent' | 'luxury';

interface IllustrationProps<N extends string> {
  name: N;
  className?: string;
}

/**
 * The one <img> every illustration renders.
 *
 * Decorative only: every place that shows one also prints the label next to
 * it, so the image is hidden from assistive technology. If the file fails to
 * load (a deploy that dropped an asset, a blocked request) it hides itself
 * rather than leave a broken-image glyph in the middle of a card; its box
 * stays, so the layout around it does not jump.
 */
export const DecorativeImage: React.FC<{ src: string; className?: string; lazy?: boolean }> = ({ src, className, lazy }) => {
  const [failedSrc, setFailedSrc] = useState<string | null>(null);
  return (
    <img
      src={src}
      alt=""
      aria-hidden="true"
      draggable={false}
      loading={lazy ? 'lazy' : undefined}
      decoding="async"
      onError={() => setFailedSrc(src)}
      style={failedSrc === src ? { visibility: 'hidden' } : undefined}
      className={`object-contain select-none ${className ?? ''}`}
    />
  );
};

export const SpecIllustration: React.FC<IllustrationProps<SpecIllustrationName>> = ({ name, className }) => (
  <DecorativeImage src={`/images/illustrations/spec/${name}.svg`} className={className} lazy />
);

export const SoftIcon: React.FC<IllustrationProps<SoftIconName>> = ({ name, className }) => (
  <DecorativeImage src={`/images/illustrations/soft/${name}.svg`} className={className ?? 'w-6 h-6'} />
);

export const NavPicture: React.FC<IllustrationProps<NavPictureName>> = ({ name, className }) => (
  <DecorativeImage src={`/images/nav/${name}.webp`} className={className ?? 'w-6 h-6'} />
);

export const CategoryPicture: React.FC<IllustrationProps<CategoryPictureName>> = ({ name, className }) => (
  <DecorativeImage src={`/images/categories/${name}.webp`} className={className} lazy />
);

/**
 * The picture for a listing's type, wherever renting or buying is shown: the
 * same keys-and-house (rent) and magnifier (buy) as the sidebar, so the two
 * read the same on every page.
 */
export const ListingTypePicture: React.FC<{ type: 'rent' | 'sale'; className?: string }> = ({ type, className }) => (
  <NavPicture name={type === 'rent' ? 'rent' : 'buy'} className={className} />
);
